mapper.select:
SELECT department.id AS dept_id, department.parent_id, department.dept_name, department.leader_user_id FROM sys_dept department WHERE department.id IN
#{departmentId}
AND department.deleted = 0 AND department.status = 0 AND NOT EXISTS ( SELECT 1 FROM sys_dept ancestor WHERE FIND_IN_SET(ancestor.id, department.ancestors) AND (ancestor.deleted != 0 OR ancestor.status = 1) )
